#!/usr/bin/env bun
/// The training workload of a profile-guided build.
///
///   bun run benchmark/pgo-train.ts <pintail binary>
///
/// Starts the given server on an empty data directory and drives it through
/// what a deployment spends its time on, with no source database: a local
/// database is created over the API and loaded over the MySQL wire, so the
/// run needs nothing but the binary. The rows are generated by formula (the
/// benchmark's own distribution), every count is checked against the same
/// formula, and the statement list is fixed, so two runs train the same
/// code.
///
/// What it covers: the wire and HTTP statement paths, parse/bind/plan, the
/// write path (WAL, memtable, flush, compaction), startup recovery, the
/// timed benchmark's Q1-Q8 and N1-N4 shapes with the wider shapes of the
/// instruction suite, session time zones, prepared statements, and a loop of
/// small statements on one connection and on several. What it cannot cover
/// without a source: snapshot copy and binlog decoding.
///
/// `PINTAIL_PGO_ROWS` (orders, default 2,000,000), `PINTAIL_PGO_EVENTS`
/// (default 400,000) and `PINTAIL_PGO_STATEMENTS` (default 20,000) scale it.
/// The caller sets `LLVM_PROFILE_FILE` (or the layout tool's own output
/// path); this script only makes the server do the work and exit cleanly,
/// which is when an instrumented binary writes its profile.
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import mysql from 'mysql2/promise'
import { benchmarkQueries } from './queries.ts'

const binary = process.argv[2]
if (!binary) {
  console.error('usage: pgo-train.ts <pintail binary>')
  process.exit(2)
}
const setting = (name: string, fallback: number) => {
  const value = Number(process.env[name] ?? fallback)
  if (!Number.isInteger(value) || value <= 0) throw new Error(`${name} must be a positive integer`)
  return value
}
const ORDERS = setting('PINTAIL_PGO_ROWS', 2_000_000)
const EVENTS = setting('PINTAIL_PGO_EVENTS', 400_000)
const STATEMENTS = setting('PINTAIL_PGO_STATEMENTS', 20_000)
const USERS = 100_000
const PRODUCTS = 10_000
const BATCH = 2_000
const DATABASE = 'training'
const STATUSES = ['pending', 'processing', 'shipped', 'delivered', 'cancelled']
const REGIONS = ['us-east', 'us-west', 'eu-west', 'eu-east', 'ap-south', 'ap-east', 'sa-east', 'af-south']
const CATEGORIES = ['electronics', 'clothing', 'food', 'books', 'toys', 'sports', 'home', 'garden', 'auto', 'health']
const CHANNELS = ['email', 'kiosk', 'phone', 'store', 'web']

const started = performance.now()
const log = (message: string) => console.log(`[pgo-train ${((performance.now() - started) / 1000).toFixed(1)}s] ${message}`)
const dataDir = mkdtempSync(join(tmpdir(), 'pintail-pgo-'))
const httpPort = 20_000 + (process.pid % 20_000)
const wirePort = httpPort + 1
const base = `http://127.0.0.1:${httpPort}`

type Server = ReturnType<typeof Bun.spawn>
let token = ''
let running: Server | null = null

async function start(env: Record<string, string>): Promise<Server> {
  const server = Bun.spawn(
    [binary, '--data-dir', dataDir, '--http-bind', `127.0.0.1:${httpPort}`, '--wire-bind', `127.0.0.1:${wirePort}`],
    { env: { ...process.env, ...env }, stdout: 'ignore', stderr: 'ignore' },
  )
  for (let attempt = 0; attempt < 600; attempt += 1) {
    if (server.exitCode !== null) throw new Error(`the server exited at startup (exit ${server.exitCode})`)
    try {
      if ((await fetch(`${base}/health`)).ok) {
        running = server
        return server
      }
    } catch {}
    await Bun.sleep(100)
  }
  throw new Error('the server did not become healthy')
}

/// A clean exit is what writes the profile, so a server that has to be
/// killed fails the run.
async function stop(server: Server) {
  server.kill('SIGTERM')
  const exited = await Promise.race([server.exited.then(() => true), Bun.sleep(120_000).then(() => false)])
  running = null
  if (!exited) {
    server.kill('SIGKILL')
    throw new Error('the server did not stop on SIGTERM; no profile was written')
  }
}

async function api<T>(path: string, body?: unknown): Promise<T> {
  const response = await fetch(`${base}${path}`, {
    method: body === undefined ? 'GET' : 'POST',
    headers: { 'content-type': 'application/json', ...(token ? { authorization: `Bearer ${token}` } : {}) },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (!response.ok) throw new Error(`${path}: ${response.status} ${await response.text()}`)
  return (await response.json()) as T
}

const pad = (value: number) => String(value).padStart(2, '0')
const cents = (value: number) => `${Math.floor(value / 100)}.${pad(value % 100)}`
const DAY = 86_400_000
/// The 1,825 days from 2020-01-01 that every date column draws from.
const DAYS = Array.from({ length: 1825 }, (_, offset) => new Date(Date.UTC(2020, 0, 1) + offset * DAY).toISOString().slice(0, 10))
const stamp = (seconds: number) => new Date(Date.UTC(2024, 0, 1) + seconds * 1000).toISOString().slice(0, 19).replace('T', ' ')

/// The benchmark's own order row for an id.
function order(id: number): string {
  const quantity = 1 + (id % 20)
  const unit = 1000 + ((id * 7919) % 99_000)
  return `(${id},${1 + ((id * 17) % USERS)},${1 + ((id * 31) % PRODUCTS)},${quantity},${cents(unit)},${cents(quantity * unit)},'${STATUSES[id % 5]}','${REGIONS[id % 8]}','${DAYS[(id * 7) % 1825]}','${DAYS[(id * 11) % 1825]} 00:00:00','2025-01-01 00:00:00')`
}
const user = (id: number) =>
  `(${id},'User_${id}','user${id}@example.com','${REGIONS[id % 8]}','${DAYS[(id * 17) % 1825]} 00:00:00','2025-01-01 00:00:00')`
const product = (id: number) =>
  `(${id},'Product_${id}','${CATEGORIES[id % 10]}',${cents(500 + ((id * 7919) % 99_500))},'${DAYS[1461 + ((id * 13) % 364)]} 00:00:00','2025-01-01 00:00:00')`
const event = (id: number) =>
  `(${id},'${stamp(id * 20)}',${cents(100 + ((id * 37) % 9_900))},'${CHANNELS[id % 5]}',${(id % 1000) - 300},'${stamp(id * 20)}')`

const SCHEMA = [
  `CREATE TABLE users (id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL,
     region VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id))`,
  `CREATE TABLE products (id INT UNSIGNED NOT NULL, name VARCHAR(200) NOT NULL, category VARCHAR(50) NOT NULL,
     price DECIMAL(10,2) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id))`,
  `CREATE TABLE orders (id BIGINT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL,
     quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL,
     status VARCHAR(20) NOT NULL, region VARCHAR(20) NOT NULL, order_date DATE NOT NULL,
     created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id))`,
  `CREATE TABLE events (id BIGINT UNSIGNED NOT NULL, occurred_at DATETIME NOT NULL, price DECIMAL(10,2) NOT NULL,
     channel VARCHAR(16) NOT NULL, amount BIGINT NOT NULL, stamp TIMESTAMP NOT NULL, PRIMARY KEY (id))`,
]

async function load(wire: mysql.Connection, table: string, rows: number, row: (id: number) => string) {
  for (let first = 1; first <= rows; first += BATCH) {
    const values: string[] = []
    for (let id = first; id < first + BATCH && id <= rows; id += 1) values.push(row(id))
    await wire.query(`INSERT INTO ${table} VALUES ${values.join(',')}`)
  }
  const [counted] = (await wire.query(`SELECT COUNT(*) AS n FROM ${table}`)) as unknown as [Array<{ n: number }>]
  if (Number(counted[0].n) !== rows) throw new Error(`${table} holds ${counted[0].n} rows, not ${rows}`)
  log(`${table}: ${rows} rows`)
}

/// The timed benchmark's statements with their cold variants, then the
/// shapes the benchmark does not have.
const ANALYTICAL: string[] = [
  ...benchmarkQueries.flatMap((query) => [query.sql, ...(query.coldVariants ?? []).map((variant) => variant.sql)]),
  "SELECT COUNT(*) AS cnt FROM orders WHERE status <> 'cancelled' AND region = 'eu-west'",
  'SELECT user_id, quantity, COUNT(*) AS cnt, SUM(total_amount) AS total FROM orders GROUP BY user_id, quantity ORDER BY cnt DESC, user_id, quantity LIMIT 10',
  'SELECT u.region, p.category, COUNT(*) AS cnt, SUM(o.total_amount) AS total FROM orders o JOIN users u ON o.user_id = u.id JOIN products p ON o.product_id = p.id GROUP BY u.region, p.category ORDER BY u.region, p.category',
  'SELECT COUNT(DISTINCT user_id) AS users, COUNT(DISTINCT product_id) AS products FROM orders',
  'SELECT id, user_id, total_amount FROM orders ORDER BY total_amount DESC, id LIMIT 25',
  'SELECT u.id, u.region, (SELECT COUNT(*) FROM orders o WHERE o.user_id = u.id) AS orders FROM users u ORDER BY u.id LIMIT 50',
  'SELECT u.id, u.name, COUNT(o.id) AS orders FROM users u LEFT JOIN orders o ON o.user_id = u.id AND o.quantity > 18 WHERE u.id <= 2000 GROUP BY u.id, u.name ORDER BY orders DESC, u.id LIMIT 20',
  "SELECT product_id, MIN(unit_price) AS low, MAX(unit_price) AS high, AVG(quantity) AS mean FROM orders WHERE region IN ('us-east', 'eu-west') GROUP BY product_id ORDER BY high DESC, product_id LIMIT 15",
  "SELECT status, region, order_date, total_amount FROM orders WHERE order_date = '2022-06-15' AND status = 'shipped' ORDER BY total_amount DESC, id LIMIT 100",
  "SELECT DATE(created_at) AS d, COUNT(*) AS cnt, SUM(total_amount) AS total FROM orders WHERE created_at >= '2021-01-01' AND created_at < '2024-01-01' GROUP BY d ORDER BY d",
  "SELECT DATE(occurred_at) AS k, COUNT(*), SUM(price) FROM events WHERE occurred_at BETWEEN '2024-02-01 00:00:00' AND '2024-03-02 00:00:00' GROUP BY k ORDER BY k",
  "SELECT HOUR(occurred_at) AS k, COUNT(*), SUM(price) FROM events WHERE occurred_at >= '2024-03-01 00:00:00' GROUP BY k ORDER BY k",
  'SELECT channel, COUNT(*) AS cnt, SUM(amount) AS total, MIN(price) AS low, MAX(price) AS high FROM events GROUP BY channel ORDER BY channel',
]

/// Statements whose answer depends on the session's time zone, each run
/// under a fixed offset and under a named zone.
const ZONED: string[] = [
  "SELECT DATE(stamp) AS k, COUNT(*), SUM(price) FROM events WHERE stamp BETWEEN '2024-02-01 00:00:00' AND '2024-03-02 00:00:00' GROUP BY k ORDER BY k",
  "SELECT DATE_FORMAT(stamp, '%Y-%m-%d') AS k, COUNT(*), SUM(price) FROM events WHERE stamp >= '2024-03-01 00:00:00' GROUP BY k ORDER BY k",
  'SELECT HOUR(stamp) AS k, COUNT(*), SUM(price) FROM events GROUP BY k ORDER BY k',
  'SELECT DATE(stamp) AS k, COUNT(*), SUM(price) FROM events GROUP BY k ORDER BY k',
]
const ZONES = ['+05:30', '-08:00', 'America/New_York']

/// The small statement an application sends thousands of times: `turn`
/// picks the shape, and the constants move with it so no two neighbours
/// are the same text.
function small(turn: number): string {
  const id = 1 + ((turn * 7919) % ORDERS)
  switch (turn % 10) {
    case 0:
      return 'SELECT 1 + 1'
    case 1:
      return `SELECT id, user_id, product_id, total_amount, status FROM orders WHERE id = ${id}`
    case 2:
      return `SELECT id, name, region FROM users WHERE id = ${1 + (id % USERS)}`
    case 3:
      return `SELECT id, status, total_amount FROM orders WHERE id BETWEEN ${id} AND ${id + 40} ORDER BY id`
    case 4:
      return `SELECT name, category, price FROM products WHERE id IN (${1 + (id % PRODUCTS)}, ${1 + ((id * 3) % PRODUCTS)}, ${1 + ((id * 7) % PRODUCTS)})`
    case 5:
      return `SELECT COUNT(*) FROM orders WHERE id > ${id} AND id <= ${id + 500} AND status = '${STATUSES[turn % 5]}'`
    case 6:
      return `SELECT CONCAT('order-', ${id}), UPPER('${REGIONS[turn % 8]}'), ${id} % 97, ROUND(${id} / 7, 2)`
    case 7:
      return `SELECT o.id, u.name FROM orders o JOIN users u ON u.id = o.user_id WHERE o.id = ${id}`
    case 8:
      return `SELECT * FROM orders WHERE id = ${id}`
    default:
      return `SELECT id, total_amount FROM orders WHERE id >= ${id} ORDER BY id LIMIT 5`
  }
}

async function connect(secret: string) {
  return mysql.createConnection({
    host: '127.0.0.1',
    port: wirePort,
    user: DATABASE,
    password: secret,
    database: DATABASE,
    dateStrings: true,
    supportBigNumbers: true,
    bigNumberStrings: true,
  })
}

async function main() {
  // Result memo off for the first run: with it on, a repeated aggregate is
  // a replay and the fold it replays is trained once.
  let server = await start({ PINTAIL_DISABLE_SETTLED_MEMO: '1' })
  token = (await api<{ token: string }>('/api/auth/setup', { email: 'training@example.com', password: 'training-workload-pass' })).token
  const database = await api<{ id: string }>('/api/databases/local', { name: DATABASE })
  const secret = (await api<{ secret: string }>(`/api/databases/${database.id}/api-keys`, { name: 'training', scopes: ['query', 'read'] })).secret
  let wire = await connect(secret)
  for (const statement of SCHEMA) await wire.query(statement)
  await load(wire, 'users', USERS, user)
  await load(wire, 'products', PRODUCTS, product)
  await load(wire, 'events', EVENTS, event)
  await load(wire, 'orders', ORDERS, order)

  // The generator's own count is the check that the engine answered, not
  // just returned: ids congruent to 2 modulo 5 are the shipped ones.
  const shipped = Math.floor((ORDERS + 3) / 5)
  const http = (sql: string) => api<{ rows: unknown[][] }>('/api/query', { db: database.id, sql })
  const counted = Number((await http("SELECT COUNT(*) AS cnt FROM orders WHERE status = 'shipped'")).rows[0][0])
  if (counted !== shipped) throw new Error(`the engine counted ${counted} shipped orders, the generator ${shipped}`)

  const analytical = async (passes: number) => {
    for (let pass = 0; pass < passes; pass += 1) {
      for (const sql of ANALYTICAL) await http(sql)
      for (const sql of ANALYTICAL) await wire.query(sql)
      for (const zone of ZONES) {
        await wire.query(`SET time_zone = '${zone}'`)
        for (const sql of ZONED) await wire.query(sql)
      }
      await wire.query("SET time_zone = '+00:00'")
    }
  }
  await analytical(3)
  log(`analytical: ${ANALYTICAL.length + ZONED.length * ZONES.length} statements, three passes, memo off`)

  for (let turn = 0; turn < STATEMENTS; turn += 1) await wire.query(small(turn))
  const [prepared] = [await wire.prepare('SELECT id, user_id, total_amount, status FROM orders WHERE id = ?')]
  for (let turn = 0; turn < STATEMENTS / 4; turn += 1) await prepared.execute([1 + ((turn * 104_729) % ORDERS)])
  await prepared.close()
  const sessions = await Promise.all(Array.from({ length: 4 }, () => connect(secret)))
  await Promise.all(
    sessions.map(async (session, index) => {
      for (let turn = index; turn < STATEMENTS / 4; turn += 4) await session.query(small(turn))
      await session.end()
    }),
  )
  log(`small statements: ${STATEMENTS} on one connection, ${STATEMENTS / 4} prepared, ${STATEMENTS / 4} across four`)
  await wire.end()
  await stop(server)

  // A restart replays the log and reopens every table; with the memo on,
  // the second pass of each aggregate is the replay path.
  server = await start({})
  wire = await connect(secret)
  await analytical(2)
  for (let turn = 0; turn < STATEMENTS / 4; turn += 1) await wire.query(small(turn))
  await wire.end()
  await stop(server)
  log('restart: recovery, the analytical list twice with the memo on')
}

let failure: unknown
try {
  await main()
  console.log(`PGO-TRAIN-DONE orders=${ORDERS} events=${EVENTS} statements=${STATEMENTS} seconds=${((performance.now() - started) / 1000).toFixed(0)}`)
} catch (error) {
  failure = error
  console.error(`PGO-TRAIN-FAIL ${error}`)
} finally {
  running?.kill('SIGKILL')
  rmSync(dataDir, { recursive: true, force: true })
}
if (failure !== undefined) process.exit(1)
// The client library keeps a timer alive after its connections close;
// nothing is left to wait for.
process.exit(0)
